def search(a, t):
    """闭区间二分:区间 [lo, hi] 两端都是候选,循环条件 lo <= hi。
    命中返回下标,否则返回 -1。"""
    lo, hi = 0, len(a) - 1
    while lo <= hi:                  # 区间非空
        mid = lo + (hi - lo) // 2    # 防溢出的习惯写法(向下取整,偏左)
        if a[mid] == t:
            return mid
        elif a[mid] < t:
            lo = mid + 1             # 左半(含 mid)都太小,丢弃
        else:
            hi = mid - 1             # 右半(含 mid)都太大,丢弃
    return -1

def search(a, t):
    """左闭右开二分:区间 [lo, hi),hi 取不到;循环条件 lo < hi。
    命中返回下标,否则返回 -1。"""
    lo, hi = 0, len(a)
    while lo < hi:                   # 区间 [lo, hi) 非空
        mid = lo + (hi - lo) // 2
        if a[mid] == t:
            return mid
        elif a[mid] < t:
            lo = mid + 1             # 收缩到 [mid+1, hi)
        else:
            hi = mid                 # 收缩到 [lo, mid),mid 已排除
    return -1

def lower_bound(a, t):
    """第一个 >= t 的下标;若全部 < t 则返回 len(a)。等价于 bisect.bisect_left。"""
    lo, hi = 0, len(a)               # 左闭右开,答案可落在 [0, len]
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < t:
            lo = mid + 1             # a[mid] 太小,答案在右侧
        else:
            hi = mid                 # a[mid] >= t,mid 可能是答案,保留
    return lo

def upper_bound(a, t):
    """第一个 > t 的下标;若全部 <= t 则返回 len(a)。等价于 bisect.bisect_right。"""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] <= t:
            lo = mid + 1             # a[mid] <= t,答案在右侧
        else:
            hi = mid                 # a[mid] > t,mid 可能是答案,保留
    return lo
